// Quita lo automático (boletines, notificaciones, no-reply) y deja los correos de personas.
// Excepción: mensajes de plataformas donde pueden llegar clientes (Workana, LinkedIn).
const MI_CORREO = 'tu-correo@gmail.com';

const PLATAFORMAS = [
  { dominio: 'workana.com', nombre: 'Workana', asunto: /nuevo mensaje|te (ha )?(enviado|escrito)|invit|propuesta (aceptada|aprobada)|te (ha )?contratado/i },
  { dominio: 'linkedin.com', nombre: 'LinkedIn', asunto: /mensaje|message|inmail|te ha enviado|sent you/i },
];

const REMITENTE_AUTOMATICO = /(no-?reply|do-?not-?reply|mailer-daemon|postmaster|bounce|notification|notificacion|newsletter|news@|marketing|promo|alerts?@|updates?@)/i;

function parsearRemitente(from = '') {
  const m = from.match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>/);
  if (m) return { nombre: m[1].trim(), correo: m[2].trim().toLowerCase() };
  return { nombre: '', correo: from.trim().toLowerCase() };
}

function esMasivo(meta = {}) {
  if (meta['list-unsubscribe'] || meta['list-id']) return true;
  if (/bulk|list|junk/i.test(meta['precedence'] || '')) return true;
  const auto = meta['auto-submitted'];
  if (auto && !/^no$/i.test(auto)) return true;
  return false;
}

// Si el monitor reinicia el flujo o se relanza una ejecución, no avisar dos veces del mismo correo.
// El correo se marca como visto en "Recordar avisado", después de que el aviso salga bien.
const vistos = $getWorkflowStaticData('global');
vistos.ids ||= [];

const salida = [];
for (const item of $input.all()) {
  const e = item.json;
  const mid = e.metadata?.['message-id'];
  if (mid && vistos.ids.includes(mid)) continue;
  const { nombre, correo } = parsearRemitente(e.from);
  const dominio = correo.split('@')[1] || '';
  const asunto = e.subject || '';

  if (correo === MI_CORREO) continue;

  const plataforma = PLATAFORMAS.find(p => dominio === p.dominio || dominio.endsWith('.' + p.dominio));
  if (plataforma) {
    if (plataforma.asunto.test(asunto)) {
      salida.push({ json: { nombre, correo, asunto, cuerpo: e.textPlain || '', html: e.textHtml || '', plataforma: plataforma.nombre, mid } });
    }
    continue;
  }

  if (REMITENTE_AUTOMATICO.test(correo) || esMasivo(e.metadata)) continue;

  salida.push({ json: { nombre, correo, asunto, cuerpo: e.textPlain || '', html: e.textHtml || '', plataforma: null, mid } });
}
return salida;

// Busca señales de cliente en asunto y primeras líneas del cuerpo.
// cliente: hay señales claras. dudoso: persona real sin señales (lo revisará la IA).
const SENALES = [
  /presupuesto/i, /cotizaci/i, /propuesta/i, /proyecto/i, /contrat/i, /servicio/i,
  /precio/i, /cu[aá]nto (cuesta|cobras|sale)/i, /necesit/i, /me interesa/i, /trabajo/i, /freelance/i,
  /p[aá]gina web|sitio web|\bweb\b|landing/i, /tienda (online|virtual)|e-?commerce/i,
  /\bapp\b|aplicaci[oó]n/i, /automatiz/i, /\bbot\b/i, /n8n/i,
  /servidor|minecraft|plugin|\bmods?\b|kubejs/i,
  /quote|budget|hire|project|website|looking for/i,
];

function limpiarCuerpo(texto, html) {
  let t = texto;
  if (!t && html) t = html.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');
  return (t || '')
    .split('\n')
    .filter(l => !l.trim().startsWith('>'))
    .join(' ')
    .split(/\b(El|On) .{5,80}(escribió|wrote):/)[0]
    .replace(/\s+/g, ' ')
    .trim();
}

return $input.all().map(item => {
  const e = item.json;
  const extracto = limpiarCuerpo(e.cuerpo, e.html).slice(0, 300);
  const texto = `${e.nombre} ${e.asunto} ${extracto}`;
  const coincidencias = SENALES.filter(r => r.test(texto)).length;
  const clasificacion = e.plataforma || coincidencias > 0 ? 'cliente' : 'dudoso';
  return { json: { nombre: e.nombre, correo: e.correo, asunto: e.asunto, extracto, plataforma: e.plataforma, coincidencias, clasificacion } };
});

