={{ (() => {
  const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const base = $json.etiqueta || 'Posible cliente';
  const titulo = $json.plataforma ? `${base} · ${$json.plataforma}` : base;
  const de = $json.nombre ? `${esc($json.nombre)} &lt;${esc($json.correo)}&gt;` : esc($json.correo);
  let m = `<b>${titulo}</b>\nDe: ${de}\nAsunto: ${esc($json.asunto) || '(sin asunto)'}`;
  if ($json.extracto) m += `\n\n<i>${esc($json.extracto)}</i>`;
  return m;
})() }}

