// Recupera el correo original y marca si lo decidió la IA o si la IA falló.
const original = $('¿Es cliente?').item.json;
const fallo = Boolean($json.error);
return { json: { ...original, etiqueta: fallo ? 'Sin clasificar (falló la IA)' : 'Posible cliente (IA)' } };

// Marca el correo como avisado (guarda los últimos 300) para no repetir el aviso.
const mid = $('Descartar automáticos').item.json.mid;
if (mid) {
  const vistos = $getWorkflowStaticData('global');
  vistos.ids = [...(vistos.ids || []).filter(x => x !== mid), mid].slice(-300);
}
return $json;
